package org.apache.commons.math.stat;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.Comparator;
import java.util.Iterator;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for org.apache.commons.math.stat.Frequency#getCumPct
 */
public class Frequency_getCumPct_TriageGen2Test {

    private static final double DELTA = 1e-10;



    @Test
    public void testGetCumPct_WithValues() {
        Frequency frequency = new Frequency();
        // Adding values to establish a distribution
        // Order of addition/values: A: 1, B: 2, C: 3 -> Total: 6
        frequency.addValue("A");
        frequency.addValue("B");
        frequency.addValue("B");
        frequency.addValue("C");
        frequency.addValue("C");
        frequency.addValue("C");

        // Total sumFreq = 6
        // CumFreq("A") = 1 -> 1/6 = 0.16666666666666666
        // CumFreq("B") = 1 + 2 = 3 -> 3/6 = 0.5
        // CumFreq("C") = 1 + 2 + 3 = 6 -> 6/6 = 1.0

        // Note: Frequency uses a TreeMap/Comparator internally. 
        // String order is A, B, C.

        assertEquals(1.0 / 6.0, frequency.getCumPct("A"), DELTA);
        assertEquals(3.0 / 6.0, frequency.getCumPct("B"), DELTA);
        assertEquals(6.0 / 6.0, frequency.getCumPct("C"), DELTA);
    }






}

