import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for org.apache.commons.math.stat.Frequency#getCumPct
 */
public class Frequency_getCumPct_TriageGen2Test {

    private static final double DELTA = 1e-10;







    @Test
    public void testGetCumPct_IntegerValues() {
        Frequency frequency = new Frequency();
        frequency.addValue(10);
        frequency.addValue(20);
        frequency.addValue(30);

        // sumFreq = 3
        // CumFreq(10) = 1 -> 1/3
        // CumFreq(20) = 2 -> 2/3
        // CumFreq(30) = 3 -> 3/3

        assertEquals(1.0 / 3.0, frequency.getCumPct(10), DELTA);
        assertEquals(2.0 / 3.0, frequency.getCumPct(20), DELTA);
        assertEquals(3.0 / 3.0, frequency.getCumPct(30), DELTA);
    }


}

